/**
 * Animar el movimiento de la tarjeta hacia la siguiente etapa.
 *
 * @param {Object} tarjeta_candidato Tarjeta del candidato.
 * @param {Object} etapa_destino Etapa destino.
 * @returns {void}
 * @author Esperanza Olivo
 */
function animarMovimientoEtapaCandidato(tarjeta_candidato, etapa_destino) {
    $('#candidato-animacion-temp').remove();

    var posicion_tarjeta = tarjeta_candidato.offset();
    var ancho_tarjeta = tarjeta_candidato.outerWidth();
    var alto_tarjeta = tarjeta_candidato.outerHeight();
    var scroll_vertical = $(window).scrollTop();

    var contenedor_destino = etapa_destino.find('.candidatos-container, .card-body').first();

    var destino = contenedor_destino.offset();
    var destino_ancho = contenedor_destino.outerWidth();

    tarjeta_candidato.css('visibility', 'hidden');
    contenedor_destino.append(tarjeta_candidato);

    var posicion_final = tarjeta_candidato.offset();

    var tarjeta_clon_candidato = tarjeta_candidato.clone().attr('id', 'candidato-animacion-temp').css({
        position: 'fixed',
        top: posicion_tarjeta.top - scroll_vertical,
        left: posicion_tarjeta.left,
        width: ancho_tarjeta,
        height: alto_tarjeta,
        margin: 0,
        zIndex: 9999,
        visibility: 'visible',
        pointerEvents: 'none',
        boxShadow: '0 8px 25px rgba(0,0,0,0.18)',
        transition: 'none'
    });

    $('body').append(tarjeta_clon_candidato);

    tarjeta_clon_candidato.animate({
        top: posicion_final.top - scroll_vertical, 
        left: destino.left + (destino_ancho - ancho_tarjeta) / 2
    }, 180, 'swing', function() {
        tarjeta_clon_candidato.remove();        
        tarjeta_candidato.css('visibility', 'visible');

    });
}

/**
 * Ejecutar el movimiento de etapa (Envio de ajax).
 *
 * @param {number} etapa_vacante_usuario_id ID de la relación.
 * @param {jQuery} etapa_siguiente Etapa destino (opcional).
 * @returns {void}
 * @author Jair Carvajal
 * @author Andres Morales
 * @author Esperanza Olivo
 */
function moverVacantesEtapaAplicante(etapa_vacante_usuario_id, etapa_siguiente = null) {
    var tiempo_inicio = Date.now();
    const DURACION_ANIMACION = 280;

    $.ajax({
        url: `/vacantes-mover-etapa-aplicante/${etapa_vacante_usuario_id}`,
        type: 'POST',
        dataType: 'json',
        headers: {'X-CSRF-TOKEN': $('meta[name="csrf-token"]').attr('content')},
        success: function(respuesta) {
            var tiempo_transcurrido = Date.now() - tiempo_inicio;
            var tiempo_espera = Math.max(0, DURACION_ANIMACION - tiempo_transcurrido);

            setTimeout(function() {
                $('#candidato-animacion-temp').remove();
                $('#modal-detalle-resultados').modal('hide');
                mostrarToast('success', respuesta.message);

                var filtros_actuales = prepararFiltrosActuales();
                cargarEtapasConCandidatos(filtros_actuales);

                if (etapa_siguiente && etapa_siguiente.length > 0) {
                    setTimeout(function() {
                        scrollHaciaEtapa(etapa_siguiente);
                    }, 300);
                }
            }, tiempo_espera);
        },
        error: function(xhr) {
            $('#candidato-animacion-temp').remove();

            var mensaje = xhr.responseJSON?.message || 'Error al mover el candidato de etapa';
            mostrarToast('danger', mensaje);

            var botones_mover_etapa = $(`.btn-mover-etapa-accion[data-etapa-vacante-usuario-id="${etapa_vacante_usuario_id}"]`);
            botones_mover_etapa.prop('disabled', false);

            $(`.candidato-card[data-etapa-vacante-usuario-id="${etapa_vacante_usuario_id}"]`).css('visibility', 'visible');
        }
    });
}

/**
